/* Burring Calculator - Service Worker (generated by the offline-pwa-github-pages skill)
   Bump the version in BOTH places when you upload a new release: CACHE below and APP_CACHE in index.html.

   RULES THIS FILE FOLLOWS (each one fixes a failure that really happened):
   1. Every app on the same github.io address shares ONE Cache Storage. Cleanup only deletes caches that start
      with this app's own PREFIX; "delete everything that is not mine" wipes the other apps' offline copies.
   2. The page body is REQUIRED and stored ONCE. Icons etc. are best effort: cache.addAll() is all-or-nothing, so a
      single missing file would cancel the whole offline save (and a big page downloaded twice fails on slow phones).
   3. Only this app's own addresses are handled, so a worker registered at the site root never hijacks another
      app's page.
   4. If the cache is empty while the worker is active (wiped by someone, or cleaned by the browser) the next online
      visit refills it. */
const PREFIX = 'burr-';
const CACHE = PREFIX + 'v1.5';
const REQUIRED = './index.html';
const OPTIONAL = ["./manifest.webmanifest", "./icon-192.png", "./icon-512.png", "./icon-512-maskable.png"];
const STRATEGY = 'network-first';            // 'cache-first' (big pages: instant, updated by version bump) | 'network-first' (3 s timeout)
const BASE = new URL('./', self.location).pathname;   // e.g. '/myapp/' or '/'

const good = res => res && res.ok && res.type === 'basic' && !res.redirected;

self.addEventListener('install', e => {
  e.waitUntil((async () => {
    try {
      const cache = await caches.open(CACHE);
      await cache.add(new Request(REQUIRED, { cache: 'reload' }));
      await Promise.all(OPTIONAL.map(u => cache.add(new Request(u, { cache: 'reload' })).catch(() => {})));
    } catch (err) {
      // Tell the open page WHY it failed so its status panel can show the reason.
      const msg = (err && err.name ? err.name + ': ' : '') + (err && err.message ? err.message : String(err));
      const cs = await self.clients.matchAll({ includeUncontrolled: true });
      cs.forEach(c => c.postMessage({ type: 'sw-install-error', msg }));
      throw err;
    }
    await self.skipWaiting();
  })());
});

self.addEventListener('activate', e => {
  e.waitUntil(
    caches.keys()
      .then(keys => Promise.all(keys.filter(k => k.indexOf(PREFIX) === 0 && k !== CACHE).map(k => caches.delete(k))))
      .then(() => self.clients.claim())
  );
});

async function page(req) {
  const cache = await caches.open(CACHE);
  const cached = await cache.match(REQUIRED);
  if (STRATEGY === 'cache-first' && cached) return cached;
  try {
    // Blocked/firewalled networks may hang instead of failing: give up after 3 s when a saved copy exists.
    const res = await Promise.race([
      fetch(req, { cache: 'no-store' }),
      new Promise((_, rej) => setTimeout(() => rej(new Error('timeout')), cached ? 3000 : 15000))
    ]);
    if (good(res)) { cache.put(REQUIRED, res.clone()).catch(() => {}); return res; }   // also refills an emptied cache
    return cached || res;                                                              // 404/5xx -> saved copy
  } catch (err) {
    return cached || Response.error();
  }
}

self.addEventListener('fetch', e => {
  const req = e.request;
  const url = new URL(req.url);
  if (req.method !== 'GET' || url.origin !== self.location.origin) return;
  if (url.pathname.indexOf(BASE) !== 0) return;                       // not this app
  if (req.mode === 'navigate' || req.destination === 'document') {
    if (url.pathname !== BASE && url.pathname !== BASE + 'index.html') return;
    e.respondWith(page(req));
    return;
  }
  e.respondWith((async () => {
    const cache = await caches.open(CACHE);
    const hit = await cache.match(req, { ignoreSearch: true });
    if (hit) return hit;
    try {
      const res = await fetch(req);
      if (good(res)) cache.put(req, res.clone()).catch(() => {});
      return res;
    } catch (err) { return Response.error(); }
  })());
});
